import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from Simple Icons (CC0) "notion".
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "light"
  },
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "dark"
  }
];

import {
  accountRouter,
  defineApp,
  defineProvider,
  oauth2,
  object,
  router,
  secrets,
  string,
  toolAnnotations,
  withApprovals,
} from "apps";
import { mcpHealth, mcpRouter } from "apps/mcp";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { botAccountInfo, readMcpSelf } from "./health.js";
import { icons } from "./icon.js";
import { options } from "./openapi.js";
import { notionVersion, withNotionVersion } from "./version.js";

// Notion's official remote MCP server. It registers clients itself (dynamic client registration and
// Client ID Metadata Documents), so signing in needs no integration of the user's own.
const mcpUrl = "https://mcp.notion.com/mcp";

const notion = defineProvider({
  name: "Notion",
  hosts: ["mcp.notion.com", "api.notion.com"],
  auth: {
    // First, so the connect page starts with it. Its tokens only work on the MCP server.
    oauth: oauth2({ discover: mcpUrl }),
    // An internal integration's secret, from notion.so/profile/integrations. Only the REST API takes it.
    token: secrets({
      label: "Internal integration secret",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  async health(check) {
    if (check.account.method === "oauth") {
      const headers = { Authorization: `Bearer ${check.account.fields.access_token}` };
      await mcpHealth(check, { url: mcpUrl, headers });
      const accountInfo = await readMcpSelf(check, mcpUrl, headers);
      check.signal.throwIfAborted();
      return accountInfo ? { accountInfo } : {};
    }
    const response = await check.fetch("https://api.notion.com/v1/users/me", {
      signal: check.signal,
      headers: {
        Authorization: `Bearer ${check.account.fields.token}`,
        "Notion-Version": notionVersion,
      },
    });
    return { accountInfo: await botAccountInfo(response) };
  },
});

export default defineApp(
  { user: { accounts: { notion: notion.many() } }, icons },
  async ({ user, cache, fetch, signal }) => {
    const accounts = user?.accounts.notion ?? [];
    return {
      tools: router(
        {
          mcp: router(
            await accountRouter(
              accounts.flatMap((account) => (account.method === "oauth" ? [account] : [])),
              async (account) =>
                withApprovals(
                  await mcpRouter({
                    url: mcpUrl,
                    account,
                    headers: { Authorization: `Bearer ${account.fields.access_token}` },
                    cache,
                    signal,
                  }),
                  (tool) => (toolAnnotations(tool)?.readOnlyHint === true ? undefined : always()),
                ),
              { signal },
            ),
            {
              title: "Notion MCP",
              description: "Notion's MCP server: search, fetch, create and update pages, databases and comments.",
            },
          ),
          api: router(
            await accountRouter(
              accounts.flatMap((account) => (account.method === "token" ? [account] : [])),
              (account) =>
                withApprovals(
                  liveOpenapiRouter({
                    ...options,
                    cache,
                    fetch: withNotionVersion(fetch),
                    signal,
                    account,
                  }),
                  (tool) => (tool.kind === "mutation" ? always() : undefined),
                ),
              { signal },
            ),
            {
              title: "Notion API",
              description:
                "Pages, data sources, databases, blocks, comments, users and search through Notion's REST API, for accounts connected with an internal integration secret.",
            },
          ),
        },
        {
          title: "Notion",
          description:
            "Pages, databases, blocks, comments, users and search in Notion workspaces, through Notion's MCP server (mcp) for signed-in accounts and the REST API (api) for internal integrations.",
          instructions:
            "Accounts connected by signing in with Notion use the mcp tools; accounts connected with an internal integration secret use the api tools.",
          icons,
        },
      ),
    };
  },
);

import type { OpenapiToolNamesOptions } from "apps/openapi";
import emptySecurity from "./empty-security.json" with { type: "json" };

// Notion's own OpenAPI document, published in the makenotion/notion-mcp-server repository, pinned to
// a commit so the patches below always match it. The document requires bearerAuth at its top level but
// marks 23 of its 24 operations `security: []` (no authentication), so no token would be sent and
// Notion would answer 401. empty-security.json lists them (scripts/empty-security.ts); the patches give
// each one the bearer requirement back.
export const options = {
  source: {
    url: "https://raw.githubusercontent.com/makenotion/notion-mcp-server/9a8a94cdfaaaac98fa5a7023ad76257bbd26ed3e/scripts/notion-openapi.json",
  },
  patches: emptySecurity.map((operation) => ({
    op: "add" as const,
    path: `${operation}/security`,
    value: [{ bearerAuth: [] }],
  })),
  kinds: { "post-search": "query", "query-data-source": "query" },
  allowedOrigin: "https://api.notion.com",
  securitySchemes: { bearerAuth: { type: "http", scheme: "bearer" } },
  methods: {
    token: [{ scheme: "bearerAuth", field: "token", part: "value", prefix: "" }],
    oauth: [{ scheme: "bearerAuth", field: "access_token", part: "value", prefix: "" }],
  },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/notion",
  "description": "Pages, databases, blocks, comments and search in Notion, through Notion's MCP server or the REST API for internal integrations.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Notion"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.11",
    "@modelcontextprotocol/sdk": "1.32.1"
  }
}

export const notionVersion = "2025-09-03";

const origin = "https://api.notion.com";

type Fetch = typeof globalThis.fetch;

// The OpenAPI document declares Notion-Version only on two operations, so the header is set here for
// every request to the Notion API. Other origins (the spec download) are left untouched.
export const withNotionVersion =
  (base: Fetch): Fetch =>
  (input, init) => {
    const url = input instanceof Request ? input.url : String(input);
    if (new URL(url).origin !== origin) return base(input, init);
    const headers = new Headers(input instanceof Request ? input.headers : undefined);
    new Headers(init?.headers).forEach((value, key) => headers.set(key, value));
    headers.set("Notion-Version", notionVersion);
    return base(input, { ...init, headers });
  };

import { decodeJson, json, object, string, type AccountCheckContext, type AuthMethods } from "apps";

const botUser = object({
  id: string(),
  bot: json().optional(),
});

/** Both Notion account methods report the workspace rather than the bot's name. */
export async function botAccountInfo(response: Response) {
  const me = await decodeJson(response, botUser);
  const bot = me.bot;
  const name =
    bot !== null && typeof bot === "object" && !Array.isArray(bot) && "workspace_name" in bot
      ? bot.workspace_name
      : undefined;
  const displayName = typeof name === "string" ? name.trim().slice(0, 255) : undefined;
  return { externalId: me.id, ...(displayName ? { displayName } : {}) };
}

type Check = {
  fetch: AccountCheckContext<AuthMethods>["fetch"];
  signal: AbortSignal;
  deadline?: number;
};

const protocolVersion = "2025-03-26";

/** A JSON-RPC error answer to the lookup; the account stays healthy and unnamed. */
class LookupFailed extends Error {}

/** The answer when `message` is the response to request `id`, else undefined. */
function reply(message: unknown, id: number): { readonly result: unknown } | undefined {
  if (message === null || typeof message !== "object" || !("id" in message) || message.id !== id)
    return undefined;
  if ("error" in message) throw new LookupFailed();
  return { result: "result" in message ? message.result : undefined };
}

/**
 * The JSON-RPC answer to request `id`: a JSON body, or the first matching event of a server-sent
 * event stream, read as it arrives so a stream the server keeps open still answers.
 */
async function answer(response: Response, id: number): Promise<unknown> {
  if (!(response.headers.get("content-type") ?? "").includes("text/event-stream")) {
    const found = reply(JSON.parse(await response.text()), id);
    if (found === undefined) throw new LookupFailed();
    return found.result;
  }
  const reader = response.body?.getReader();
  if (reader === undefined) throw new LookupFailed();
  const decoder = new TextDecoder();
  let buffer = "";
  try {
    for (;;) {
      const { value, done } = await reader.read();
      buffer += decoder.decode(value, { stream: !done });
      const events = buffer.split(/\r?\n\r?\n/);
      buffer = done ? "" : (events.pop() ?? "");
      for (const event of events) {
        const data = event
          .split(/\r?\n/)
          .filter((line) => line.startsWith("data:"))
          .map((line) => line.slice(5).replace(/^ /, ""))
          .join("\n");
        if (data === "") continue;
        let message: unknown;
        try {
          message = JSON.parse(data);
        } catch {
          continue;
        }
        const found = reply(message, id);
        if (found !== undefined) return found.result;
      }
      if (done) throw new LookupFailed();
    }
  } finally {
    await reader.cancel().catch(() => {});
  }
}

/**
 * The optional identity read: Notion's read-only `notion-get-self` tool over the MCP server's
 * streamable HTTP endpoint. It shares the check's cancellation and remaining deadline, and a lookup
 * that fails or names nothing leaves the verified account healthy.
 */
export async function readMcpSelf(check: Check, url: string, headers: Record<string, string>) {
  check.signal.throwIfAborted();
  const remaining = Math.min(5_000, (check.deadline ?? Date.now() + 5_250) - Date.now() - 250);
  if (remaining <= 0) return;
  const signal = AbortSignal.any([check.signal, AbortSignal.timeout(Math.floor(remaining))]);
  let session: string | undefined;
  let version: string | undefined;
  const post = (body: object) =>
    check.fetch(url, {
      method: "POST",
      signal,
      headers: {
        ...headers,
        "content-type": "application/json",
        accept: "application/json, text/event-stream",
        ...(session === undefined ? {} : { "mcp-session-id": session }),
        ...(version === undefined ? {} : { "mcp-protocol-version": version }),
      },
      body: JSON.stringify({ jsonrpc: "2.0", ...body }),
    });
  try {
    const initialized = await post({
      id: 1,
      method: "initialize",
      params: {
        protocolVersion,
        capabilities: {},
        clientInfo: { name: "notion-account-check", version: "1.0.0" },
      },
    });
    if (!initialized.ok) return void (await initialized.body?.cancel());
    session = initialized.headers.get("mcp-session-id") ?? undefined;
    const started = await answer(initialized, 1);
    version =
      started !== null &&
      typeof started === "object" &&
      "protocolVersion" in started &&
      typeof started.protocolVersion === "string"
        ? started.protocolVersion
        : protocolVersion;
    const notified = await post({ method: "notifications/initialized" });
    await notified.body?.cancel();
    const called = await post({
      id: 2,
      method: "tools/call",
      params: { name: "notion-get-self", arguments: {} },
    });
    if (!called.ok) return void (await called.body?.cancel());
    const result = await answer(called, 2);
    if (result === null || typeof result !== "object") return;
    if ("isError" in result && result.isError === true) return;
    const content = "content" in result && Array.isArray(result.content) ? result.content : [];
    const values: unknown[] = [
      "structuredContent" in result ? result.structuredContent : undefined,
      ...content.flatMap((item: unknown) => {
        if (
          item === null ||
          typeof item !== "object" ||
          !("type" in item) ||
          item.type !== "text" ||
          !("text" in item) ||
          typeof item.text !== "string"
        )
          return [];
        try {
          return [JSON.parse(item.text)];
        } catch {
          return [];
        }
      }),
    ];
    for (const value of values) {
      try {
        return await botAccountInfo(Response.json(value));
      } catch {
        /* Try the next text block. */
      }
    }
  } catch {
    // Credential verification already passed; a naming failure is not an unhealthy account.
  } finally {
    // DELETE has its own short signal so an expired lookup can still close its session.
    if (session !== undefined)
      await check
        .fetch(url, {
          method: "DELETE",
          signal: AbortSignal.timeout(100),
          headers: {
            ...headers,
            "mcp-session-id": session,
            "mcp-protocol-version": version ?? protocolVersion,
          },
        })
        .then((response) => response.body?.cancel())
        .catch(() => {});
  }
  check.signal.throwIfAborted();
}
